window.kbPageData["views/entry/k-f1683fc311e9cc73"] = {"key":"entry/k-f1683fc311e9cc73","state":{"route":"entry/k-f1683fc311e9cc73"},"node":{"id":"k-f1683fc311e9cc73","mode":"k","title":"压条繁殖","type":"方法与技能","domain":"科技","reading":"","intro":"","priority":100,"aliases":["压条常用于月季、米兰等木本花卉繁殖"],"qs":["国考 2024 副省级 行测#18"],"current":false,"candidates":true,"sources":[],"basisGroup":"","authority":null,"sourceOnly":false,"reviewSet":"单次条目","independentCount":1,"repeatPositions":0,"directorySummary":"压条是让仍与母株相连的枝条或茎蔓先在基质中生根，再将其分离成新植株的繁殖方法。月季、米兰等木本花卉常用此法。","review":{"definition":"压条是让仍与母株相连的枝条或茎蔓先在基质中生根，再将其分离成新植株的繁殖方法。月季、米兰等木本花卉常用此法。","explanation":"压条在生根前保留枝条与母株的连接，扦插通常先取下插穗，再促使其生根。许多多肉植物常用扦插或分株繁殖，B项把压条概括为多肉植物的常用繁殖方式，因此错误。","references":[],"evidence":"此法常用于木本花卉繁殖，如月季、米兰等","disposition":"独立词条","basis":"据原题和解析编释。"}},"questions":{"国考 2024 副省级 行测#18":{"paper":"国考 2024 副省级 行测","n":18,"mod":"常识判断","src":["a566fec37e508ca7f975.pdf",3],"asrc":["a475ecf57d968bc14cd6.pdf",7],"card":"29bdc58b03d26372c5d9fc2a","links":[{"id":"k-f1683fc311e9cc73","role":"解题依据","why":"压条的典型适用对象可用于判断它是否为多肉植物的常用繁殖方式。"}]}},"terms":{},"references":{},"topics":[],"units":{"k-f1683fc311e9cc73":[["国考 2024 副省级 行测#18"]]}};
